mapper.select:
with DYGLF as ( select DISTINCT a.FINPROD_ID ,CASE WHEN CORORG IS NULL THEN 'N' ELSE 'Y' END CORORG from (select m.FINPROD_ID, case when m.FINPROD_TYPE2 = 'F01' then m.ISSUER else m.FINANCIER end org_code FROM FIN_PRODUCT m INNER JOIN FIN_PRODUCT_TYPE fpt ON m.FINPROD_ID=fpt.FINPROD_ID AND fpt.BRANCH=0 AND ( (fpt.TYPE_8 ='F06' and fpt.TYPE_6 IN('P01','P11')) OR ( fpt.TYPE_8 ='F01' AND fpt.TYPE_6 ='B18'))) a left join (SELECT ORG_NO,COUNT(COR_ORGID) AS CORORG FROM INF_ORG_CORRELATION WHERE ORG_NO <> COR_ORGID GROUP BY ORG_NO) b ON a.org_code=b.ORG_NO ) select m.FINPROD_ID finprodId, m.FINPROD_ABBR finprodAbbr, m.FINPROD_NAME finprodName, m.VDATE, m.MDATE, m.PROFIT_TYPE profitType, m.CALENDAR_ID calendarId, m.FINPROD_MARKET_ID finprodMarketId, m.TRADE_MARKET tradeMarket, m.ISSUE_TYPE issueType, n.INVEST_NATURE investNature, y.TYPE_4 type4, y.TYPE_5 type5, y.TYPE_8 type6, y.TYPE_6 type7, y.TYPE_9 type9, y.TYPE_10 type10, s.REP_ASSET_TYPE repAssetDept, ZtPingji.GRADE_RESULT bodyGradeType, ZxPingji.GRADE_RESULT bondGradeType, m.ISSUER_CODE as issuerCode, Mingdan.LIST_LEVEL listLevel, DYGLF.CORORG as isCorOrg from (select FIN_PRODUCT.* ,case FINPROD_TYPE2 WHEN 'F01' THEN ISSUER WHEN 'F06' THEN manager WHEN 'F07' THEN ISSUER WHEN 'F10' THEN ISSUER WHEN 'F18' THEN financier WHEN 'F17' THEN manager ELSE null end as ISSUER_CODE from FIN_PRODUCT) m inner join FIN_PRODUCT_ADD n on m.FINPROD_ID=n.FINPROD_ID inner join FIN_PRODUCT_TYPE y on m.FINPROD_ID=y.FINPROD_ID and y.BRANCH='0' left join REP_ASSET_DEPT s on m.FINPROD_ID=s.REP_FINPROD_ID left join (SELECT LIST_LEVEL,LIST_DETAIL_ID FROM (SELECT n.LIST_LEVEL,m.LIST_DETAIL_ID,rank() over( partition BY LIST_DETAIL_ID ORDER BY LIST_LEVEL) AS rowno FROM RSK_ACCESS_LIST_DETAIL m INNER JOIN RSK_ACCESS_LIST n ON m.LIST_ID =n.LIST_ID AND m.LIST_DETAIL_ID IS NOT null AND m.LIST_DATE <=to_date('${valDate}','yyyy-MM-dd') AND n.LIST_LEVEL IN ('01','02') AND m.LIST_DETAIL_TYPE='02') WHERE rowno=1 ) Mingdan ON Mingdan.LIST_DETAIL_ID=m.FINPROD_MARKET_ID LEFT JOIN (SELECT tempData.O_CODE,tempData.GRADE_RESULT FROM (SELECT A41.O_CODE,A41.GRADE_RESULT,rank() over( partition by A41.O_CODE order by A41.GRADE_DATE desc, A41.GRADE_RESULT DESC) AS rowNo FROM MST_BOND_CREDIT_RATING A41 WHERE O_TYPE='01' AND GRADE_DATE <=to_date('${valDate}','yyyy-MM-dd')) tempData WHERE tempData.rowNo=1
) ZtPingji ON ZtPingji.O_CODE=m.FINPROD_MARKET_ID LEFT JOIN (SELECT tempData.O_CODE,tempData.GRADE_RESULT FROM (SELECT A41.O_CODE,A41.GRADE_RESULT,rank() over( partition by A41.O_CODE order by A41.GRADE_DATE desc, A41.GRADE_RESULT DESC) AS rowNo FROM MST_BOND_CREDIT_RATING A41 WHERE O_TYPE='02' AND GRADE_DATE <=to_date('${valDate}','yyyy-MM-dd')) tempData WHERE tempData.rowNo=1 ) ZxPingji ON ZxPingji.O_CODE=m.FINPROD_MARKET_ID left join DYGLF on m.FINPROD_ID=DYGLF.FINPROD_ID
m.FINPROD_ID in
#{item}
union all
select m.FINPROD_ID finprodId, decode(y.TYPE_8, 'F07', '交易型资产_债券质押式回购_' , 'F08', '交易型资产_拆借_', '交易型资产_衍生品交易_') || m.FINPROD_ID finprodAbbr, decode(y.TYPE_8, 'F07', '交易型资产_债券质押式回购_' , 'F08', '交易型资产_拆借_', '交易型资产_衍生品交易_') || m.FINPROD_ID finprodName, m.VDATE, m.MDATE, m.PROFIT_TYPE profitType, m.CALENDAR_ID calendarId, m.FINPROD_ID finprodMarketId, m.TRADE_MARKET tradeMarket, null issueType, decode(y.TYPE_8, 'F07', decode(y.TYPE_7, '04', '01', ''), 'F08', decode(y.TYPE_7, '02', '01', ''), '03') investNature, y.TYPE_4 type4, y.TYPE_5 type5, y.TYPE_8 type6, y.TYPE_7 type7, y.TYPE_9 type9, y.TYPE_10 type10, s.REP_ASSET_TYPE repAssetDept, null as bodyGradeType, null as bondGradeType, null as relOrgCode, null as listLevel, null as isCorOrg from FIN_TRADE_PRODUCT m inner join FIN_PRODUCT_TYPE y on m.FINPROD_ID=y.FINPROD_ID and m.BRANCH='0' and y.BRANCH='0' and m.FINPROD_TYPE <> 'F21' left join REP_ASSET_DEPT s on m.FINPROD_ID=s.REP_FINPROD_ID
mdate >= to_date('${valDate}','yyyy-MM-dd')
and m.FINPROD_ID in
#{item}

SELECT PARA_CODE,RKEY,RVALUE FROM (
    SELECT 
       PARA_CODE || ':' || PARA_GRANULARITY PARA_CODE,
       NVL(PORTFOLIO_ID,'') || decode(NVL(PORTFOLIO_ID,''),'','',decode(NVL(ASSET_CODE,''),'','',',')) || NVL(ASSET_CODE,'') RKEY,
       sum(CHANGE_VALUE) RVALUE 
    FROM RSK_INDICATOR_PARA_CALCDETAIL
    WHERE SUP_DATE = #{valDate, jdbcType=DATE}
    GROUP BY PARA_CODE,PARA_GRANULARITY,PORTFOLIO_ID,ASSET_CODE
)

    PARA_CODE = #{paraCode, jdbcType=VARCHAR}

    AND RKEY in

        #{item}

select UNITE_ID uniteId, PRT_BAG_ID prtBagId, IND_ID indId from RSK_INDIVID_UNITE
UNITE_ID in (select UNITE_ID from RSK_INDIVID_UNITE a where a.IND_ID in
#{item}
)

select UNITE_ID uniteId, PRT_BAG_ID prtBagId, IND_ID indId, START_DATE startDate, END_DATE endDate, UNITE_TYPE uniteType, FINPROD_ID finprodId, WARN_COND warnCond, APPROVE_COND approveCond, FOUL_COND foulCond from RSK_INDIVID_SPECIAL_STAGE
UNITE_TYPE=#{uniteType}
and IND_ID in
#{item}

select DEL_ID delId, PRT_BAG_ID prtBagId, IND_ID indId, START_DATE startDate, END_DATE endDate, FINPROD_ID finprodId from RSK_INDIVID_ASSET_DEL
IND_ID in
#{item}

select DISTINCT PORTFOLIO_ID from RSK_PORTFOLIO_PACKAGE_DTL


    PTL_BAG_ID in

        #{item}

select
COMMON_BUSINESS_TYPE commonBusinessType,
PARA_CODE paraCode,
REDIS_MODEL redisModel
from RSK_BUSINESS_REDIS_CONFIG


        and COMMON_BUSINESS_TYPE in ${commonBusinessType}


        and PARA_CODE = #{paraCode}


        and REDIS_MODEL = #{paraCode}
